# §50.5's certificate matrix needs certificates. These are committed.
#
# Locally made, as §50.5 requires: "Reproducing a system trust store in CI
# is the hard part. The practical approach is to test the trust EVALUATOR
# against a store the test controls." Nothing here touches the developer's or
# CI machine's Keychain, and nothing reaches the internet — §50.5 also says
# external internet tests must never be required for CRAN checks.
#
# Until review #193 the fixture was generated by the openssl CLI at test
# time, and skipped itself when generation failed; one CLI change retired
# the whole matrix on every Linux leg for months (2026-09-25). The two CAs
# and ten leaves now live in fixtures/tls/, made by tools/make-tls-fixture,
# whose PROVENANCE file says when and with what. The CLI is still used to
# SERVE them (openssl s_server) and to compute an independent pin; a
# present CLI with a missing certificate is a failure, not a skip.

tls_fixture_dir <- function() testthat::test_path("fixtures", "tls")

openssl_bin <- function() {
  p <- Sys.which("openssl")
  if (!nzchar(p)) NULL else unname(p)
}

tls_fixture <- function() {
  d <- tls_fixture_dir()
  f <- function(...) file.path(d, paste0(...))
  paths <- list(
    dir = d,
    ca = f("ca.pem"),
    rogue_ca = f("rogueca.pem"),
    cert = function(n) f(n, ".pem"),
    key = function(n) f(n, ".key")
  )
  for (n in c(
    "ca",
    "rogueca",
    "good",
    "wronghost",
    "untrusted",
    "ip",
    "ipother",
    "ipdns",
    "cnonly",
    "clientonly",
    "expired",
    "notyet"
  )) {
    if (!file.exists(paths$cert(n)) || !file.exists(paths$key(n))) {
      stop(
        "the TLS fixture is incomplete: ",
        n,
        " is missing from ",
        d,
        "; run tools/make-tls-fixture",
        call. = FALSE
      )
    }
  }
  paths
}

# The DER bytes of a PEM certificate, and the UTCTime values in it, for the
# expiry guard in test-certs.R: base R only, so the guard does not depend on
# the CLI whose absence it must survive.
openssl_der <- function(pem_lines) {
  b64 <- paste(
    grep("^[A-Za-z0-9+/=]+$", pem_lines, value = TRUE),
    collapse = ""
  )
  vals <- match(strsplit(b64, "")[[1]], c(LETTERS, letters, 0:9, "+", "/")) - 1L
  vals[is.na(vals)] <- 0L # '=' padding: decoded, then dropped below
  n <- length(vals) %/% 4 * 4
  q <- matrix(vals[seq_len(n)], nrow = 4)
  out <- rbind(
    q[1, ] * 4 + q[2, ] %/% 16,
    (q[2, ] %% 16) * 16 + q[3, ] %/% 4,
    (q[3, ] %% 4) * 64 + q[4, ]
  )
  pad <- sum(strsplit(b64, "")[[1]] == "=")
  as.raw(as.vector(out))[seq_len(n %/% 4 * 3 - pad)]
}

der_utc_times <- function(der) {
  # Every UTCTime (tag 0x17, length 13) in the DER, as Dates.
  i <- which(der == as.raw(0x17))
  i <- i[i + 14 <= length(der) & der[i + 1] == as.raw(13)]
  txt <- vapply(i, function(k) rawToChar(der[(k + 2):(k + 14)]), "")
  txt <- txt[grepl("^[0-9]{12}Z$", txt)]
  yy <- as.integer(substr(txt, 1, 2))
  as.Date(sprintf(
    "%d-%s-%s",
    ifelse(yy < 50, 2000L + yy, 1900L + yy),
    substr(txt, 3, 4),
    substr(txt, 5, 6)
  ))
}

# Kept for the rows that name a dated certificate: with the fixture
# committed, a missing one is the failure tls_fixture() raises.
skip_unless_cert <- function(name) {
  invisible(tls_fixture()$cert(name))
}

# The §14.4 pin of a fixture certificate, computed by the openssl CLI rather
# than by zuhttp, so a pin test compares zuhttp's digest with an independent
# one (#12, S7 criterion 4). SHA-256 over the DER SubjectPublicKeyInfo.
spki_pin <- function(cert) {
  fx <- tls_fixture()
  o <- shQuote(openssl_bin())
  cmd <- sprintf(
    paste(
      "%s x509 -in %s -pubkey -noout | %s pkey -pubin -outform der",
      "| %s dgst -sha256 -binary | %s base64 -A"
    ),
    o,
    shQuote(fx$cert(cert)),
    o,
    o,
    o
  )
  b64 <- suppressWarnings(system2(
    "sh",
    c("-c", shQuote(cmd)),
    stdout = TRUE,
    stderr = FALSE
  ))
  if (length(b64) != 1L || !grepl("^[A-Za-z0-9+/]{43}=$", b64)) {
    testthat::skip(paste("could not compute the pin of", cert))
  }
  paste0("sha256//", b64)
}

# Serve `cert` over TLS on loopback for the duration of `code`, which receives
# the base URL. openssl s_server -www answers any request with a small page,
# which is all the matrix needs — what is under test is the handshake.
# `host` is the name the URL uses: the #246 rows connect by IP literal.
with_tls_server <- function(cert, code, host = "localhost", args = "") {
  fx <- tls_fixture()
  port <- NULL
  for (attempt in 1:8) {
    p <- free_port()
    pidf <- tempfile("zu-s_server-")
    system2(
      "sh",
      c(
        "-c",
        shQuote(sprintf(
          "echo $$ > %s; exec %s s_server -cert %s -key %s -accept %d -www -quiet %s",
          pidf,
          openssl_bin(),
          fx$cert(cert),
          fx$key(cert),
          p,
          args
        ))
      ),
      wait = FALSE,
      stdout = NULL,
      stderr = NULL
    )

    deadline <- Sys.time() + 10
    up <- FALSE
    while (Sys.time() < deadline) {
      con <- try(
        suppressWarnings(socketConnection(
          "127.0.0.1",
          p,
          open = "r+b",
          timeout = 1,
          blocking = TRUE
        )),
        silent = TRUE
      )
      if (!inherits(con, "try-error")) {
        close(con)
        up <- TRUE
        break
      }
      Sys.sleep(0.1)
    }
    # A port that answered is only ours if s_server is still running: one that
    # failed to bind (the port was taken) exits, and the probe then succeeded
    # against someone else's listener, so the handshake below was aborted by
    # a server that never spoke TLS. Seen once under shuffle (OSStatus -9816
    # and -9836); not reproduced in isolation, so this closes the one hole
    # that explains it rather than a confirmed cause.
    Sys.sleep(0.1)
    if (up && file.exists(pidf)) {
      pid <- as.integer(readLines(pidf, warn = FALSE)[[1]])
      up <- isTRUE(tools::pskill(pid, 0L))
    }
    if (up) {
      port <- p
      break
    }
    if (file.exists(pidf)) {
      try(
        tools::pskill(
          as.integer(readLines(pidf, warn = FALSE)[[1]]),
          tools::SIGKILL
        ),
        silent = TRUE
      )
    }
  }
  if (is.null(port)) {
    # The CLI is present (skip_unless_local_tls) and the certificate is
    # committed, so a server that does not come up is a failure (#193).
    stop("could not start openssl s_server on any of 8 ports", call. = FALSE)
  }
  on.exit(
    {
      if (file.exists(pidf)) {
        try(
          tools::pskill(
            as.integer(readLines(pidf, warn = FALSE)[[1]]),
            tools::SIGKILL
          ),
          silent = TRUE
        )
      }
      unlink(pidf)
    },
    add = TRUE
  )

  code(sprintf("https://%s:%d/", host, port))
}

skip_unless_local_tls <- function() {
  testthat::skip_on_cran()
  skip_under_gctorture()
  if (.Platform$OS.type != "unix") {
    testthat::skip("the fixture uses a POSIX shell")
  }
  if (is.null(openssl_bin())) {
    testthat::skip("openssl CLI not available")
  }
  # Every row of the matrix names its roots with ca_file.
  skip_unless_tls_supports("ca_file")
}

# A CA that is real, correctly formed, and trusts nothing on the internet.
# That is what distinguishes "adds to" from "replaces": with it added, a
# public host still validates; with it substituted, the same host must not.
# Shared with the §50.5 matrix in test-certs.R via helper-tlsfixture.R rather
# than generated twice — two fixtures for one concept drift.
local_ca <- function() {
  fx <- tls_fixture()
  list(dir = fx$dir, pem = fx$ca)
}

# For test-tls.R's D-56 cases: one config per setting some backend cannot
# honour.
unsupported_cases <- function() {
  # PEM-shaped, so check_tls()'s PEM check passes and the capability check is
  # what decides; the certificate itself is never parsed on this path.
  pem <- tempfile(fileext = ".pem")
  writeLines(
    c("-----BEGIN CERTIFICATE-----", "MIIB", "-----END CERTIFICATE-----"),
    pem
  )
  list(
    pins = zu_tls(
      pins = "sha256//YLh1dUR9y6Kja30RrAn7JKnbQG/uEtLMkBgFF2Fuihg="
    ),
    tls13 = zu_tls(min_version = 13),
    ca_file = zu_tls(ca_file = pem),
    ca_extra = zu_tls(ca_extra = pem),
    revocation = zu_tls(revocation = TRUE)
  )
}
